<section aria-labelledby="dashboard-title"><h2 id="dashboard-title">Resumen de eventos y reservas</h2><p class="field-help">Datos al <?= $date($dashboard['as_of']) ?> (Costa Rica). Actividad: eventos publicados y futuros; reservas confirmadas de esos eventos.</p>
<dl class="dashboard-grid">
<?php foreach (['total_events' => 'Total de eventos conservados', 'active_events' => 'Eventos activos', 'active_reservations' => 'Reservas activas', 'reserved_entries' => 'Entradas reservadas'] as $key => $label): ?><div class="metric"><dt><?= $label ?></dt><dd><?= $escape($dashboard[$key]) ?></dd></div><?php endforeach; ?>
<div class="metric"><dt>Ocupación global</dt><dd><?= $escape($dashboard['occupation']) ?> %<p class="field-help metric-note"><?= $escape($dashboard['reserved_entries']) ?> entradas sobre <?= $escape($dashboard['total_capacity']) ?> espacios.</p></dd></div>
<div class="metric"><dt>Ingresos potenciales</dt><dd><?= Eventify\Support\Format::money((string) $dashboard['potential_revenue']) ?><p class="field-help metric-note">Total histórico de reservas activas. No representa pagos recibidos.</p></dd></div>
