<div class="event-grid admin-list">
<article class="event-card"><h3>Evento con más entradas reservadas</h3><?php if ($dashboard['top_event_id'] === null): ?><p>Aún no hay reservas activas.</p><?php else: ?><p><a href="/admin/eventos/<?= (int) $dashboard['top_event_id'] ?>/editar"><?= $escape($dashboard['top_event_name']) ?></a></p><p><?= $escape($dashboard['top_event_entries']) ?> entradas.</p><?php if ((int) $dashboard['top_event_ties'] > 1): ?><p class="field-help">Empate entre <?= (int) $dashboard['top_event_ties'] ?> eventos; se muestra el de menor identificador.</p><?php endif; ?><?php endif; ?></article>
<article class="event-card"><h3>Categoría con más entradas reservadas</h3><?php if ($dashboard['top_category_id'] === null): ?><p>Aún no hay reservas activas.</p><?php else: ?><p><?= $escape($dashboard['top_category_name']) ?></p><p><?= $escape($dashboard['top_category_entries']) ?> entradas.</p><?php if ((int) $dashboard['top_category_ties'] > 1): ?><p class="field-help">Empate entre <?= (int) $dashboard['top_category_ties'] ?> categorías; se muestra la de menor identificador.</p><?php endif; ?><?php endif; ?></article>
